# Wrap the interactive zone in a fragment so only this specific function reruns on click
@st.fragment
def heatmap_interactive_zone():
    st.markdown("### 👈 Click anywhere on the Heatmap")

    # A. Generate dummy Heatmap data
    np.random.seed(42)
    z_data = np.random.rand(8, 8)
    fig = px.imshow(z_data, text_auto=".2f")

    # B. Render natively (Perfectly inherits Dark/Light themes and toolbars)
    st.plotly_chart(fig, use_container_width=True, key="native_heatmap")

